#include <stdio.h>

int main(void) {
    int C, D, T;
    if (scanf("%d %d %d", &C, &D, &T) != 3) return 0;

    /* Combustivel necessario no tanque (em litros): (D - T*C) / C
       Queremos o valor em decimos de litro, calculado com aritmetica exata.
       decimos = (D - T*C) * 10 / C   (se positivo; caso contrario, 0) */
    long long need = (long long)D - (long long)T * C;
    long long tenths;

    if (need <= 0) {
        tenths = 0;               /* ja ha combustivel suficiente */
    } else {
        long long num = need * 10;            /* decimos exatos */
        /* arredondamento para o inteiro mais proximo (empates para cima) */
        tenths = (2 * num + C) / (2 * C);
        if (tenths < 0) tenths = 0;
    }

    printf("%lld.%lld\n", tenths / 10, tenths % 10);
    return 0;
}
